#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <float.h>

__global__ void min_reduce_dim1_kernel(const float* __restrict__ x,
                                        float* __restrict__ out,
                                        int batch, int dim1, int dim2) {
    int total = batch * dim2;
    int stride_grid = blockDim.x * gridDim.x;
    for (int idx = blockIdx.x * blockDim.x + threadIdx.x; idx < total; idx += stride_grid) {
        int b = idx / dim2;
        int c = idx - b * dim2;
        const float* base = x + (size_t)b * (size_t)dim1 * (size_t)dim2 + c;
        // Use multiple independent accumulators to break the serial dependency
        // chain of fminf reductions, allowing more memory-level parallelism
        // (overlapping loads) while still reading the same coalesced pattern.
        float min0 = FLT_MAX;
        float min1 = FLT_MAX;
        float min2 = FLT_MAX;
        float min3 = FLT_MAX;
        float min4 = FLT_MAX;
        float min5 = FLT_MAX;
        float min6 = FLT_MAX;
        float min7 = FLT_MAX;
        int i = 0;
        int dim1_aligned = dim1 - (dim1 % 8);
        const size_t stride = (size_t)dim2;
        const size_t stride2 = stride * 2;
        const size_t stride3 = stride * 3;
        const size_t stride4 = stride * 4;
        const size_t stride5 = stride * 5;
        const size_t stride6 = stride * 6;
        const size_t stride7 = stride * 7;
        const size_t stride8 = stride * 8;
        const float* p = base;
        #pragma unroll 8
        for (; i < dim1_aligned; i += 8) {
            float v0 = __ldg(&p[0]);
            float v1 = __ldg(&p[stride]);
            float v2 = __ldg(&p[stride2]);
            float v3 = __ldg(&p[stride3]);
            float v4 = __ldg(&p[stride4]);
            float v5 = __ldg(&p[stride5]);
            float v6 = __ldg(&p[stride6]);
            float v7 = __ldg(&p[stride7]);
            min0 = fminf(min0, v0);
            min1 = fminf(min1, v1);
            min2 = fminf(min2, v2);
            min3 = fminf(min3, v3);
            min4 = fminf(min4, v4);
            min5 = fminf(min5, v5);
            min6 = fminf(min6, v6);
            min7 = fminf(min7, v7);
            p += stride8;
        }
        for (; i < dim1; ++i) {
            float v = __ldg(p);
            min0 = fminf(min0, v);
            p += stride;
        }
        float min_val = fminf(fminf(fminf(min0, min1), fminf(min2, min3)),
                                fminf(fminf(min4, min5), fminf(min6, min7)));
        out[idx] = min_val;
    }
}
torch::Tensor min_reduce_dim1_cuda(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(x.dim() == 3, "x must be 3D (batch, dim1, dim2)");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    int batch = x.size(0);
    int dim1  = x.size(1);
    int dim2  = x.size(2);
    auto out = torch::empty({batch, dim2}, x.options());
    const int threads = 256;
    int total = batch * dim2;
    int needed_blocks = (total + threads - 1) / threads;
    // Memory-bound reduction kernel: avoid a partial (tail) wave by
    // rounding the grid size up to a full multiple of the number of
    // blocks that can run concurrently across all SMs. Extra blocks
    // beyond 'needed_blocks' simply have no work (guarded by the
    // grid-stride loop bound), so correctness is unaffected while the
    // scheduler no longer has to execute an inefficient partial wave.
    int device_id = 0;
    cudaGetDevice(&device_id);
    cudaDeviceProp prop;
    cudaGetDeviceProperties(&prop, device_id);
    int blocks_per_sm = 0;
    cudaOccupancyMaxActiveBlocksPerMultiprocessor(&blocks_per_sm, min_reduce_dim1_kernel, threads, 0);
    int wave_size = prop.multiProcessorCount * (blocks_per_sm > 0 ? blocks_per_sm : 1);
    int blocks = needed_blocks;
    if (wave_size > 0) {
        blocks = ((needed_blocks + wave_size - 1) / wave_size) * wave_size;
    }
    min_reduce_dim1_kernel<<<blocks, threads>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        batch, dim1, dim2
    );
    cudaError_t err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "CUDA kernel launch failed: ", cudaGetErrorString(err));
    return out;
